const VERSION = 'THEIBS_ACTION_CONDITIONED_V1';
const TARGET = 'PRIVATE_INFORMATION_SET_COMMITMENT_VALUE';
const ORIGIN = 'OUTWARD_ROUNDED_INFORMATION_SET_BEST_RESPONSE_SADDLE_BOUNDS';
